"""PlatformIO pre-build script: embed web/index.html as a PROGMEM C string.
The UI is kept in its own editable HTML file, while LittleFS remains log-only.
"""
from pathlib import Path
Import("env")  # provided by PlatformIO/SCons

project_dir = Path(env.subst("$PROJECT_DIR"))
source = project_dir / "web" / "index.html"
target = project_dir / "include" / "GeneratedWebPage.h"
html = source.read_text(encoding="utf-8")
delimiter = "DIGITALEBIKEWEB"
if ")" + delimiter + '"' in html:
    raise RuntimeError("The HTML contains the raw-string terminator")
content = (
    "// AUTO-GENERATED by tools/embed_webpage.py. Do not edit.\n"
    "#pragma once\n"
    "#include <Arduino.h>\n"
    "static const char INDEX_HTML[] PROGMEM = R\"" + delimiter + "(\n"
    + html + "\n)" + delimiter + "\";\n"
)
if not target.exists() or target.read_text(encoding="utf-8") != content:
    target.write_text(content, encoding="utf-8")
print("DigitalEBike: embedded web/index.html")
